// Manual adjacent ABI migration generated by `pina migrations make`.
// Source version: 1 (4 bytes)
// Destination version: 2 (variable bytes)
// Converts the fixed `amount: u16` into a compact decimal `code: String<5>`.
pub(crate) fn target_size(data: &[u8]) -> Option<usize> {
	if data.len() < 4 {
		return None;
	}
	let amount = u16::from_le_bytes([data[2], data[3]]);
	let mut digits = 1;
	let mut remaining = amount / 10;
	while remaining > 0 {
		digits += 1;
		remaining /= 10;
	}
	Some(3 + digits)
}

#[allow(clippy::unnecessary_wraps)]
pub(crate) fn working_size(data: &[u8], target_size: usize) -> Option<usize> {
	Some(data.len().max(target_size))
}

pub(crate) fn migrate(data: &mut [u8]) {
	if data.len() < 4 {
		return;
	}
	let amount = u16::from_le_bytes([data[2], data[3]]);
	let mut digits = [0_u8; 5];
	let mut count = 0;
	let mut remaining = amount;
	loop {
		digits[count] = b'0' + u8::try_from(remaining % 10).unwrap_or(0);
		count += 1;
		remaining /= 10;
		if remaining == 0 || count == digits.len() {
			break;
		}
	}
	if remaining > 0 {
		digits = *b"99999";
		count = digits.len();
	}
	digits[..count].reverse();
	data[3..3 + count].copy_from_slice(&digits[..count]);
	data[2] = u8::try_from(count).unwrap_or(0);
}
